def _extract_embedded_music():
    """Grava as músicas embutidas em music/ (ou numa pasta temporária se não der)."""
    global MUSIC_DIR
    for folder in (MUSIC_DIR, os.path.join(__import__("tempfile").gettempdir(), "torneio12_music")):
        try:
            os.makedirs(folder, exist_ok=True)
            for fname, data in MUSIC_B64.items():
                dest = os.path.join(folder, fname)
                if not os.path.isfile(dest) or os.path.getsize(dest) == 0:
                    with open(dest, "wb") as fh:
                        fh.write(base64.b64decode(data))
            MUSIC_DIR = folder
            return
        except OSError:
            continue

