SFX = {}
sfx_volume = 0.5


def _tone(freqs, dur, vol=0.35, wave="square"):
    rate, _fmt, chans = pygame.mixer.get_init()
    buf = array("h")
    for f in freqs:
        n = int(rate * dur)
        for i in range(n):
            ph = 2 * math.pi * f * i / rate
            if wave == "square":
                s = 1.0 if math.sin(ph) >= 0 else -1.0
            elif wave == "noise":
                s = random.uniform(-1, 1)
            else:
                s = math.sin(ph)
            v = int(32767 * vol * s * (1 - i / n))
            for _ in range(chans):
                buf.append(v)
    return pygame.mixer.Sound(buffer=buf.tobytes())


def _build_sfx():
    if not mixer_ready:
        return
    try:
        if pygame.mixer.get_init()[1] != -16:
            return
        SFX.update({"click": _tone([880], .05), "ok": _tone([660, 990], .08),
                    "bad": _tone([220, 150], .13, .4),
                    "win": _tone([523, 659, 784, 1047], .13, .35, "sine")})
    except Exception:
        SFX.clear()


def play_sfx(name):
    s = SFX.get(name)
    if s:
        try:
            s.set_volume(sfx_volume)
            s.play()
        except Exception:
            pass


