view = {"s": 1.0, "ox": 0, "oy": 0}
_present = {"size": None, "surf": None}


def present():
    global window
    window = pygame.display.get_surface()
    ww, wh = window.get_size()
    s = min(ww / LW, wh / LH)
    tw, th = max(1, int(LW * s)), max(1, int(LH * s))
    ox, oy = (ww - tw) // 2, (wh - th) // 2
    view["s"], view["ox"], view["oy"] = s, ox, oy
    window.fill((0, 0, 0))
    if (tw, th) == (LW, LH):
        window.blit(screen, (ox, oy))
    else:
        if _present["size"] != (tw, th):
            _present["surf"] = pygame.Surface((tw, th)).convert()
            _present["size"] = (tw, th)
        try:
            pygame.transform.smoothscale(screen, (tw, th), _present["surf"])
            window.blit(_present["surf"], (ox, oy))
        except ValueError:
            window.blit(pygame.transform.scale(screen, (tw, th)), (ox, oy))
    pygame.display.flip()


def to_logical(pos):
    return ((pos[0] - view["ox"]) / view["s"], (pos[1] - view["oy"]) / view["s"])


                                                                                                                              
                                                                                                 
                                                                                                             
