def clamp(v, lo, hi):
    return max(lo, min(hi, v))


def mix(a, b, t):
    return tuple(int(a[i] + (b[i] - a[i]) * t) for i in range(3))


def dim(c, f):
    return tuple(clamp(int(v * f), 0, 255) for v in c)


def R(x, y, w, h):
    return pygame.Rect(int(x), int(y), int(w), int(h))


                                                                     
                                                                                          
                                                                              
