def _load_asset_image(fn):
    """Procura em assets/ primeiro (permite trocar o desenho); senão usa o embutido no arquivo."""
    path = os.path.join(ASSETS_DIR, fn)
    try:
        if os.path.isfile(path):
            return pygame.image.load(path).convert_alpha()
        data = EMBEDDED_ASSETS.get(fn)
        if data:
            return pygame.image.load(io.BytesIO(base64.b64decode(data)), fn).convert_alpha()
    except (pygame.error, OSError, ValueError):
        pass
    return None


def get_sprite(name):
    if name in _sprite_cache:
        return _sprite_cache[name]
    sp = None
    fn, frames, fps = SPRITES[name]
    img = _load_asset_image(fn)
    if img is not None:
        fw = img.get_width() // max(1, frames)
        sp = {"frames": [img.subsurface((i * fw, 0, fw, img.get_height())).copy()
                         for i in range(frames)], "fps": fps}
    _sprite_cache[name] = sp
    return sp


def draw_sprite(surf, name, midbottom, height, t=0.0, progress=None, flip=False):
    sp = get_sprite(name)
    if not sp:
        return False
    n = len(sp["frames"])
    if progress is not None:
        i = min(n - 1, int(clamp(progress, 0, 0.999) * n))
    elif n > 1 and sp["fps"] > 0:
        i = int(t * sp["fps"]) % n
    else:
        i = 0
    h = int(height)
    ck = (name, i, h, flip)
    if ck not in _scaled_cache:
        img = sp["frames"][i]
        w = max(1, int(img.get_width() * h / img.get_height()))
        sc = pygame.transform.smoothscale(img, (w, h))
        if flip:
            sc = pygame.transform.flip(sc, True, False)
        _scaled_cache[ck] = sc
    sc = _scaled_cache[ck]
    surf.blit(sc, sc.get_rect(midbottom=(int(midbottom[0]), int(midbottom[1]))))
    return True


                                                                   
