_PIX = 4
_oloko_frames = {}


def _pixel_parchment(w, h):
    """Pergaminho pixel art com moldura de madeira laranja (desenhado em baixa resolução e ampliado sem suavizar)."""
    lw, lh = (w + _PIX - 1) // _PIX, (h + _PIX - 1) // _PIX
    low = pygame.Surface((lw, lh))
    rnd = random.Random(w * 31 + h)
    OUT, OR_HI, OR, OR_LO = (82, 42, 22), (236, 154, 56), (204, 114, 34), (150, 78, 26)
    CREAM, TAN, TAN_LO, TAN_HI = (242, 226, 186), (214, 172, 112), (198, 154, 96), (226, 190, 134)
    low.fill(OUT)
    pygame.draw.rect(low, OR_HI, (1, 1, lw - 2, lh - 2))
    pygame.draw.rect(low, OR, (2, 2, lw - 3, lh - 3))
    pygame.draw.rect(low, OR_LO, (lw - 3, 2, 1, lh - 3))
    pygame.draw.rect(low, OR_LO, (2, lh - 3, lw - 3, 1))
    pygame.draw.rect(low, OUT, (4, 4, lw - 8, lh - 8))
    pygame.draw.rect(low, CREAM, (5, 5, lw - 10, lh - 10))
    x0, y0, x1, y1 = 6, 6, lw - 6, lh - 6
    for y in range(y0, y1):
        for x in range(x0, x1):
            u, v = (x - x0) / max(1, x1 - x0), (y - y0) / max(1, y1 - y0)
            edge = min(u, 1 - u, v, 1 - v)
            col = TAN
            blob = (u - .5) ** 2 / .16 + (v - .62) ** 2 / .30
            if edge < 0.07 and rnd.random() < 0.32 - edge * 3:
                col = TAN_LO
            elif blob < 0.5 or (blob < 1 and rnd.random() < (1 - blob) * 1.3):
                col = TAN_LO
            elif rnd.random() < 0.03:
                col = TAN_HI if rnd.random() < .5 else TAN_LO
            low.set_at((x, y), col)
    f = min(9, lw // 6)
    for a in range(f):
        for b in range(f):
            px, py = x1 - f + a, y0 + b
            if a > b:
                low.set_at((px, py), OR_LO)
            elif a == b:
                low.set_at((px, py), OUT)
            else:
                low.set_at((px, py), CREAM if a < b - 1 else TAN_LO)
    pygame.draw.rect(low, OR, (x0 - 1, lh // 4, 2, 3))
    pygame.draw.rect(low, OR, (x1 - 1, lh // 2, 2, 3))
    big = pygame.transform.scale(low, (lw * _PIX, lh * _PIX))
    out = pygame.Surface((w, h), pygame.SRCALPHA)
    out.blit(big, (0, 0))
    return out


def oloko_frame(rect, title="PROF. OLOKO"):
    """Fundo do retrato do Oloko: pergaminho pixel art com moldura laranja e fita de título."""
    rect = pygame.Rect(rect)
    key = (rect.w, rect.h)
    if key not in _oloko_frames:
        _oloko_frames[key] = _pixel_parchment(rect.w, rect.h)
    sh = pygame.Surface((rect.w, rect.h), pygame.SRCALPHA)
    sh.fill((0, 0, 0, 90))
    screen.blit(sh, (rect.x + 5, rect.y + 6))
    screen.blit(_oloko_frames[key], rect.topleft)
    if title:
        f = font(12, True)
        tw = f.size(title)[0] + 52
        tab = R(rect.x + 22, rect.y - 15, tw, 28)
        draw_ribbon(screen, tab.centerx, tab.centery, tab.width, tab.height, mix(WINE, GOLD, .22), None)
        draw_text(title, tab.centerx, tab.centery, 12, WHITE, bold=True)


def button(label, rect, action, selected=False, disabled=False, small=False, color=CYAN, hint=None):
    rect = pygame.Rect(rect)
    hover = rect.collidepoint(mouse_pos) and not disabled
    if disabled:
        base, edge = (50, 38, 30), (70, 54, 42)
    elif selected:
        base, edge = (112, 40, 50), color
    elif hover:
        base, edge = (122, 82, 48), color
    else:
        base, edge = (88, 58, 36), DARKLINE
    screen.blit(wood_surface(rect.width, rect.height, base, edge, 7, rect.width > 90, 4, True), rect.topleft)
    if selected and not disabled:
                                                                         
        pulse = .5 + .5 * math.sin(pygame.time.get_ticks() / 260)
        pygame.draw.rect(screen, mix(edge, WHITE, .2 + .3 * pulse), rect.inflate(-2, -2), 1)
    col = MUTED if disabled else (GOLD if selected else (WHITE if hover else PALE))
    draw_text(str(label).upper(), rect.centerx, rect.centery, 15 if small else 20, col, bold=True)
    if hint:
        draw_text(hint, rect.right - 14, rect.centery, 11, MUTED, align="right")
    if action and not disabled:
        buttons.append((rect, action))
    return rect


