def wood_bar(x, y, w, h, frac, col):
    """Barra de progresso: sulco de madeira com preenchimento colorido."""
    pygame.draw.rect(screen, (30, 18, 12), (x, y, w, h))
    fw = int(w * clamp(frac, 0, 1))
    if fw > 0:
        pygame.draw.rect(screen, col, (x, y, fw, h))
        pygame.draw.rect(screen, mix(col, WHITE, .4), (x, y, fw, 3))
        pygame.draw.rect(screen, mix(col, INK, .45), (x, y + h - 3, fw, 3))
    pygame.draw.rect(screen, (150, 108, 60), (x, y, w, h), 2)


def draw_arrow(surf, cx, cy, s, d, color, outline=None):
    base = [(0, -1), (.95, -.05), (.42, -.05), (.42, .95), (-.42, .95), (-.42, -.05), (-.95, -.05)]
    pts = []
    for x, y in base:
        if d == "UP":
            px, py = x, y
        elif d == "DOWN":
            px, py = x, -y
        elif d == "LEFT":
            px, py = y, x
        else:
            px, py = -y, x
        pts.append((cx + px * s, cy + py * s))
    pygame.draw.polygon(surf, color, pts)
    if outline:
        pygame.draw.polygon(surf, outline, pts, 2)


def keycap(text, cx, cy, w=46, h=46, color=CYAN, size=20, arrow=None, lit=False):
    """Tecla de madeira entalhada."""
    r = R(cx - w / 2, cy - h / 2, w, h)
    pygame.draw.rect(screen, SHADOW, r.move(0, 6))
    pygame.draw.rect(screen, (58, 36, 22), r.move(0, 3))
    top = (150, 104, 60) if lit else (112, 76, 46)
    pygame.draw.rect(screen, top, r)
    pygame.draw.line(screen, mix(top, WHITE, .3), (r.x + 2, r.y + 2), (r.right - 3, r.y + 2), 2)
    pygame.draw.rect(screen, INK, r, 2)
    pygame.draw.rect(screen, color, r.inflate(-6, -6), 1)
    if arrow:
        draw_arrow(screen, r.centerx, r.centery, min(w, h) * .3, arrow, WHITE, INK)
    else:
        draw_text(text, r.centerx, r.centery, size, WHITE, bold=True, shadow=False)


def draw_crest(cx, cy, radius, color, label="12"):
    r = max(8, int(radius))
    draw_shield(screen, cx, cy, int(r * 1.7), int(r * 2.0), mix(color, INK, .45), color)
    draw_text(label, cx, cy - 2, max(12, int(r * .65)), WHITE, bold=True)


_portrait_cache = {}
_portrait_scaled = {}


def get_portrait(idx):
    """Retrato da casa idx. Prioridade: assets/casa_01.png ... casa_12.png; senão o embutido no fim do arquivo."""
    if idx in _portrait_cache:
        return _portrait_cache[idx]
    img = None
    try:
        path = os.path.join(ASSETS_DIR, "casa_%02d.png" % (idx + 1))
        if os.path.isfile(path):
            img = pygame.image.load(path).convert()
        elif idx < len(PORTRAIT_B64):
            img = pygame.image.load(io.BytesIO(base64.b64decode(PORTRAIT_B64[idx]))).convert()
    except Exception:
        img = None
    _portrait_cache[idx] = img
    return img


def draw_portrait(idx, cx, cy, size, border=None):
    size = int(size)
    img = get_portrait(idx)
    if img is None:
        draw_crest(cx, cy, size * .32, HOUSES[idx][1], "%02d" % (idx + 1))
        return
    key = (idx, size)
    if key not in _portrait_scaled:
        _portrait_scaled[key] = pygame.transform.smoothscale(img, (size, size))
    sc = _portrait_scaled[key]
    rect = sc.get_rect(center=(int(cx), int(cy)))
    screen.blit(sc, rect)
    if border is not None:
        pygame.draw.rect(screen, INK, rect.inflate(10, 10), 5)
        pygame.draw.rect(screen, border, rect.inflate(4, 4), 3)


OLOKO_POSES = {"talk": "oloko", "point": "oloko_point", "think": "oloko_think",
               "thumb": "oloko_thumb", "win": "oloko_win"}


def draw_oloko(x, y, size, pose="talk"):
    """Foto do Oloko (pés/base em y + size*.8). Poses: talk, point, think, thumb, win."""
    name = OLOKO_POSES.get(pose, "oloko")
    sp = get_sprite(name)
    if sp:
        img = sp["frames"][0]
        h = size * 2.1
        w = h * img.get_width() / img.get_height()
        if w > size * 2.8:
            h = size * 2.8 * img.get_height() / img.get_width()
        draw_sprite(screen, name, (x, y + size * .8), h)
        return
    r = size
    pygame.draw.ellipse(screen, (32, 19, 13), R(x - r * .55, y + r * .55, r * 1.1, r * .28))
    body = [(x - r * .7, y + r * .8), (x - r * .48, y - r * .05), (x + r * .48, y - r * .05), (x + r * .7, y + r * .8)]
    pygame.draw.polygon(screen, (115, 72, 47), body)
    pygame.draw.polygon(screen, CYAN, body, 2)
    pygame.draw.rect(screen, (244, 195, 174), R(x - r * .16, y - r * .16, r * .32, r * .3))
    pygame.draw.ellipse(screen, (247, 207, 185), R(x - r * .36, y - r * .7, r * .72, r * .72))
    pygame.draw.polygon(screen, (70, 44, 29), [(x - r * .42, y - r * .43), (x - r * .36, y - r * .72),
                                              (x - r * .05, y - r * .82), (x + r * .37, y - r * .69),
                                              (x + r * .42, y - r * .38), (x + r * .17, y - r * .55),
                                              (x - r * .12, y - r * .49)])
    pygame.draw.rect(screen, (68, 42, 28), R(x - r * .22, y - r * .42, r * .12, r * .12))
    pygame.draw.rect(screen, (68, 42, 28), R(x + r * .10, y - r * .42, r * .12, r * .12))
    pygame.draw.line(screen, GOLD, (x - r * .12, y - r * .20), (x + r * .12, y - r * .20), 2)
