def _paper_wave(s, base_y, amp, period, col, phase):
    """Camada de papel recortado em ondas, com sombra projetada na camada de trás."""
    top = []
    for x in range(0, LW + 8, 8):
        top.append((x, base_y - amp * abs(math.sin(x / period * math.pi + phase))))
    sh = pygame.Surface((LW, LH), pygame.SRCALPHA)
    pygame.draw.polygon(sh, (0, 0, 0, 80), [(0, LH)] + [(x, y - 10) for x, y in top] + [(LW, LH)])
    s.blit(sh, (0, 0))
    pygame.draw.polygon(s, col, [(0, LH)] + top + [(LW, LH)])
    pygame.draw.lines(s, mix(col, WHITE, .16), False, top, 2)


def _paper_cloud(s, cx, cy, col, scale=1.0):
    parts = ((-34, 6, 20), (-12, -8, 26), (16, -4, 24), (38, 8, 18), (0, 12, 22))
    for dx, dy, r in parts:
        pygame.draw.circle(s, (44, 16, 40), (int(cx + (dx + 5) * scale), int(cy + (dy + 7) * scale)), int(r * scale))
    for dx, dy, r in parts:
        pygame.draw.circle(s, col, (int(cx + dx * scale), int(cy + dy * scale)), int(r * scale))


def _curtains(s):
    """Cortinas de veludo roxo nas laterais, com pregas e vinco dourado."""
    for x in range(0, 46):
        p = .52 + .48 * abs(math.sin(x * .33))
        c = (int(112 * p), int(30 * p), int(104 * p))
        pygame.draw.line(s, c, (x, 0), (x, LH))
        pygame.draw.line(s, c, (LW - 1 - x, 0), (LW - 1 - x, LH))
    for x in (42, LW - 43):
        pygame.draw.line(s, (176, 128, 62), (x, 0), (x, LH), 3)
    for side in (0, 1):
        x = 22 if side == 0 else LW - 23
        pygame.draw.line(s, (200, 150, 70), (x - 14, 440), (x + 14, 440), 5)
        pygame.draw.polygon(s, (214, 164, 78), [(x, 444), (x - 7, 470), (x + 7, 470)])
        for k in (-5, 0, 5):
            pygame.draw.line(s, (170, 122, 56), (x + k, 470), (x + k, 486), 2)


def _damask_tile(sz, base, hi):
    t = pygame.Surface((sz, sz))
    t.fill(base)
    c = sz // 2
    pygame.draw.polygon(t, hi, [(c, 5), (c + 9, c), (c, sz - 5), (c - 9, c)])
    pygame.draw.ellipse(t, hi, (c - 26, c - 8, 22, 16))
    pygame.draw.ellipse(t, hi, (c + 4, c - 8, 22, 16))
    pygame.draw.circle(t, base, (c, c), 6)
    pygame.draw.circle(t, hi, (c, c), 3)
    for px, py in ((0, 0), (sz, 0), (0, sz), (sz, sz), (c, 0), (c, sz), (0, c), (sz, c)):
        pygame.draw.circle(t, hi, (px, py), 6)
        pygame.draw.circle(t, base, (px, py), 2)
    return t


def build_bg(full):
    s = pygame.Surface((LW, LH))
    if full:
        for y in range(LH):
            t = y / LH
            if t < .55:
                c = mix((20, 12, 44), (98, 40, 86), t / .55)
            else:
                c = mix((98, 40, 86), (178, 80, 84), (t - .55) / .45)
            pygame.draw.line(s, c, (0, y), (LW, y))
        _paper_cloud(s, 160, 246, (200, 92, 104), 1.0)
        _paper_cloud(s, 1120, 236, (96, 54, 122), 1.1)
        for by, amp, per, col, ph in ((470, 16, 210, (84, 36, 92), .4), (520, 18, 170, (112, 40, 90), 1.7),
                                      (574, 20, 150, (138, 52, 92), 2.9), (632, 22, 130, (96, 34, 70), 4.1),
                                      (684, 20, 120, (62, 24, 50), 5.3)):
            _paper_wave(s, by, amp, per, col, ph)
    else:
        tile = _damask_tile(84, (38, 20, 30), (55, 31, 41))
        for y in range(0, LH, 84):
            for x in range(0, LW, 84):
                s.blit(tile, (x, y))
        for y in range(LH):                                                              
            a = abs(y / LH - .45) * 2
            sh = pygame.Surface((LW, 1), pygame.SRCALPHA)
            sh.fill((12, 4, 6, int(120 * clamp(a, 0, 1) ** 1.5)))
            s.blit(sh, (0, y))
    _curtains(s)
    return s


def _make_crescent(r):
    s = pygame.Surface((r * 2 + 10, r * 2 + 10), pygame.SRCALPHA)
    c = (r + 5, r + 5)
    pygame.draw.circle(s, (250, 224, 140), c, r)
    for cx, cy, cr in ((-28, -12, 8), (-36, 14, 5), (-20, 32, 6), (-8, -34, 5)):
        pygame.draw.circle(s, (230, 192, 108), (c[0] + cx, c[1] + cy), cr)
    pygame.draw.circle(s, (0, 0, 0, 0), (c[0] + int(r * .42), c[1] - int(r * .2)), int(r * .88))
    return s


def _make_star(size):
    pts = []
    for i in range(10):
        ang = math.pi * i / 5 - math.pi / 2
        rr = size if i % 2 == 0 else size * .45
        pts.append((size + 3 + math.cos(ang) * rr, size + 3 + math.sin(ang) * rr))
    s = pygame.Surface((size * 2 + 6, size * 2 + 6), pygame.SRCALPHA)
    pygame.draw.polygon(s, (250, 212, 104), pts)
    pygame.draw.polygon(s, (196, 140, 54), pts, 2)
    return s


_DECOR = {}
HANGING_STARS = ((72, 74, 14, 0.3), (262, 156, 16, 1.4), (292, 62, 10, 2.2), (1012, 96, 15, 0.9),
                 (1098, 166, 18, 2.6), (1192, 70, 12, 1.8))


def _decor_surfaces():
    if not _DECOR:
        _DECOR["moon"] = _make_crescent(58)
        sh = _DECOR["moon"].copy()
        sh.fill((0, 0, 0, 90), special_flags=pygame.BLEND_RGBA_MULT)
        _DECOR["moon_sh"] = sh
        for _, _, sz, _ in HANGING_STARS:
            _DECOR[("star", sz)] = _make_star(sz)
    return _DECOR


def draw_hanging_decor(now):
    d = _decor_surfaces()
                              
    ax, ln = 176, 128
    a = math.sin(now * .9) * .05
    cx, cy = ax + math.sin(a) * ln, math.cos(a) * ln
    pygame.draw.line(screen, (236, 196, 176), (ax, 0), (int(cx), int(cy) - 40), 1)
    moon = pygame.transform.rotate(d["moon"], -a * 57.3)
    sh = pygame.transform.rotate(d["moon_sh"], -a * 57.3)
    screen.blit(sh, sh.get_rect(center=(int(cx) + 7, int(cy) + 9)))
    screen.blit(moon, moon.get_rect(center=(int(cx), int(cy))))
    for sx, sl, sz, ph in HANGING_STARS:
        a = math.sin(now * 1.1 + ph) * .09
        x, y = sx + math.sin(a) * sl, math.cos(a) * sl
        pygame.draw.line(screen, (236, 196, 176), (sx, 0), (int(x), int(y)), 1)
        st = pygame.transform.rotate(d[("star", sz)], -a * 57.3)
        sw_ = pygame.transform.rotate(d[("star", sz)], -a * 57.3)
        sw_.fill((0, 0, 0, 90), special_flags=pygame.BLEND_RGBA_MULT)
        screen.blit(sw_, sw_.get_rect(center=(int(x) + 5, int(y) + 7)))
        screen.blit(st, st.get_rect(center=(int(x), int(y))))


def build_scan():
    """Vinheta de vela + moldura de madeira (desenhada por cima de tudo)."""
    vw, vh = 64, 36
    small = pygame.Surface((vw, vh), pygame.SRCALPHA)
    for y in range(vh):
        for x in range(vw):
            dx = (x / (vw - 1) - .5) * 2
            dy = (y / (vh - 1) - .5) * 2
            d = math.sqrt(dx * dx * .75 + dy * dy) / 1.2
            a = int(clamp((d - .42) / .75, 0, 1) ** 1.7 * 175)
            small.set_at((x, y), (22, 8, 4, a))
    s = pygame.transform.smoothscale(small, (LW, LH))
    cols = [INK, INK, (74, 48, 28), (104, 70, 40), (128, 88, 48), (104, 70, 40), (74, 48, 28),
            (176, 130, 64), (214, 168, 82), INK]
    for i, c in enumerate(cols):
        pygame.draw.rect(s, (c[0], c[1], c[2], 255), (i, i, LW - 2 * i, LH - 2 * i), 1)
    for cx, cy in ((15, 15), (LW - 16, 15), (15, LH - 16), (LW - 16, LH - 16)):
        _nail(s, cx, cy, GOLD, 6)
    return s


BG_FULL = build_bg(True)
BG_DIM = build_bg(False)
SCAN = build_scan()


def draw_background(full=False):
    screen.blit(BG_FULL if full else BG_DIM, (0, 0))
    now = pygame.time.get_ticks() / 1000
    if full:
        for sx, sy, r, ph in STARS:
            if sy > 280 or sx < 50 or sx > LW - 50:
                continue
            p = .55 + .45 * math.sin(now * 1.6 + ph)
            col = (int(150 + 100 * p), int(110 + 90 * p), int(70 + 70 * p))
            pygame.draw.circle(screen, col, (int(sx), int(sy)), r)
            if r >= 3 and p > .9:
                pygame.draw.line(screen, GOLD, (sx - 6, sy), (sx + 6, sy), 1)
                pygame.draw.line(screen, GOLD, (sx, sy - 6), (sx, sy + 6), 1)
        draw_hanging_decor(now)
                                     
    for ex, ey, spd, ph, sz in EMBERS:
        y = (ey - now * spd) % LH
        x = ex + math.sin(now * .8 + ph) * 18
        a = .5 + .5 * math.sin(now * 2.2 + ph)
        pygame.draw.circle(screen, mix((120, 58, 30), (255, 196, 108), a), (int(x), int(y)), sz)


