_rank_cache = {"t": -99999, "data": None}


def load_ranking():
    try:
        with open(RANKING_FILE, "r", encoding="utf-8") as f:
            data = json.load(f)
        if not isinstance(data, dict):
            return {d: [] for d in DIFF_ORDER}
        return {d: data.get(d, []) if isinstance(data.get(d, []), list) else [] for d in DIFF_ORDER}
    except (OSError, json.JSONDecodeError):
        return {d: [] for d in DIFF_ORDER}


def get_ranking():
    now = pygame.time.get_ticks()
    if _rank_cache["data"] is None or now - _rank_cache["t"] > 2000:
        _rank_cache["data"] = load_ranking()
        _rank_cache["t"] = now
    return _rank_cache["data"]


def save_ranking(data):
    temp = RANKING_FILE + ".tmp"
    with open(temp, "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, indent=2)
    os.replace(temp, RANKING_FILE)
    _rank_cache["data"] = None


def register_result():
                                                                                                
    if not nickname.strip():
        return "Resultado não registrado no ranking (nickname não informado)."
    data = load_ranking()
    existing = None
    for item in data[difficulty]:
        if item.get("nickname", "").casefold() == nickname.casefold():
            existing = item
            break
    entry = {"nickname": nickname, "total": int(total_score), "quiz": int(quiz_score),
             "race": int(race_score), "balance": int(balance_score), "house": HOUSE_NAME, "race_seconds": round(race_elapsed, 2),
             "seconds": round(current_run_seconds, 2)}
    if existing:
        if entry["total"] > int(existing.get("total", 0)) or (
                entry["total"] == int(existing.get("total", 0)) and
                entry["seconds"] < float(existing.get("seconds", 999999))):
            data[difficulty].remove(existing)
            data[difficulty].append(entry)
            message = "Novo recorde pessoal registrado!"
        else:
            message = "Seu recorde anterior continua valendo."
    else:
        data[difficulty].append(entry)
        message = "Resultado registrado no ranking!"
    data[difficulty].sort(key=lambda x: (-int(x.get("total", 0)), float(x.get("seconds", 999999))))
    data[difficulty] = data[difficulty][:100]
    try:
        save_ranking(data)
    except OSError:
        message = "Não foi possível salvar o ranking. Verifique a permissão da pasta."
    return message


                                                                                  
def start_new_run():
    global page, quiz_category_index, quiz_score, quiz_raw_score, quiz_done
    global total_score, current_run_seconds, run_started_at, end_message, race_score, race_elapsed, balance_score
    quiz_category_index = 0
    quiz_score = 0
    quiz_raw_score = 0
