BAL_DUR = 20.0                                        
BAL_CONTROL = 2.4                                
BAL_DAMP = 1.3                                              
BAL_UNSTABLE = 0.9                                                                           
BAL_X0, BAL_X1 = 120, 1080                                               
BAL_CX = (BAL_X0 + BAL_X1) // 2
BAL_HALF = (BAL_X1 - BAL_X0) // 2
BAL_BEAM_Y = 292
BAL_GAUGE = pygame.Rect(BAL_X0, 356, BAL_X1 - BAL_X0, 32)
BAL_LEFT_RECT = R(236, 604, 390, 96)
BAL_RIGHT_RECT = R(654, 604, 390, 96)
bal = {}
balance_score = 0
_bal_tmp = pygame.Surface((340, 340), pygame.SRCALPHA)
_gauge_cache = {}
_bal_bg = {}


def cover_surface(img, w, h):
    f = max(w / img.get_width(), h / img.get_height())
    sc = pygame.transform.smoothscale(img, (int(img.get_width() * f) + 1, int(img.get_height() * f) + 1))
    out = pygame.Surface((w, h))
    out.blit(sc, ((w - sc.get_width()) // 2, (h - sc.get_height()) // 2))
    return out


def balance_bg():
    if "s" not in _bal_bg:
        s = pygame.Surface((SW, SH))
        photo = get_sprite("bg_equilibrio")
        if photo:
            s.blit(cover_surface(photo["frames"][0], SW, SH), (0, 0))
            veil = pygame.Surface((SW, SH), pygame.SRCALPHA)
            veil.fill((4, 6, 24, 120))
            s.blit(veil, (0, 0))
        else:
            L = race_layers()
            s.blit(L["sky"], (0, 0))
            s.blit(L["far"], (0, 0))
            s.blit(L["mid"], (0, 0))
            draw_ground(s, 0.0)
        _bal_bg["s"] = s
    return _bal_bg["s"]


def gauge_surface(zone):
    if zone not in _gauge_cache:
        g = pygame.Surface((BAL_GAUGE.width, BAL_GAUGE.height))
        half = BAL_GAUGE.width / 2
        for x in range(BAL_GAUGE.width):
            d = abs(x - half) / half
            if d <= zone:
                c = (40, 220, 110)
            elif d <= zone + 0.18:
                c = (230, 220, 60)
            elif d <= zone + 0.40:
                c = (240, 150, 50)
            else:
                c = (230, 60, 70)
            pygame.draw.line(g, c, (x, 0), (x, BAL_GAUGE.height))
        _gauge_cache[zone] = g
    return _gauge_cache[zone]


def start_balance():
    global page, balance_score
    cfg = DIFFICULTIES[difficulty]
    bal.clear()
    bal.update(phase="countdown", cd=3.0, t=0.0, p=0.0, v=0.0, wind=0.0, wind_goal=0.0, wind_t=0.0,
               in_zone=0.0, zone=cfg["bal_zone"], strength=cfg["bal_wind"], hold=0, shake=0.0,
               finish_t=0.0, popups=[], walk=0.0)
    balance_score = 0
    page = "balance"


def finish_balance():
    global balance_score, total_score, current_run_seconds, ranking_message, end_message
    mx = DIFFICULTIES[difficulty]["bal_max"]
    balance_score = int(round(clamp(bal["in_zone"] / BAL_DUR, 0, 1) * mx))
    total_score = int(quiz_score) + int(race_score) + int(balance_score)
    current_run_seconds = max(0.01, (pygame.time.get_ticks() - run_started_at) / 1000)
    ranking_message = register_result()
    end_message = "Demo: as provas 04 (Memória) e 05 (Arremesso) chegam em breve."
    show_result("PROVA 03 // EQUILÍBRIO", balance_score, mx, "ceremony_go", "VER RESULTADO FINAL >>")


def update_balance(dt):
    b = bal
    if not b:
        return
    b["shake"] = max(0.0, b["shake"] - dt)
    for p in b["popups"]:
        p[1] -= 40 * dt
        p[4] -= dt
    b["popups"][:] = [p for p in b["popups"] if p[4] > 0]
    keys = pygame.key.get_pressed()
    held = 0
    if keys[pygame.K_LEFT] or keys[pygame.K_a]:
        held -= 1
    if keys[pygame.K_RIGHT] or keys[pygame.K_d]:
        held += 1
    if pygame.mouse.get_pressed()[0]:
        if BAL_LEFT_RECT.collidepoint(mouse_pos):
            held -= 1
        elif BAL_RIGHT_RECT.collidepoint(mouse_pos):
            held += 1
    b["hold"] = clamp(held, -1, 1)
    ph = b["phase"]
    if ph == "countdown":
        b["cd"] -= dt
        if b["cd"] <= 0:
            b["phase"] = "run"
            b["popups"].append([BAL_CX, 130, "VAI!", LIME, 1.0])
    elif ph == "run":
        b["t"] += dt
        b["wind_t"] -= dt
        if b["wind_t"] <= 0:
            b["wind_t"] = random.uniform(0.5, 1.2)
            b["wind_goal"] = random.uniform(-1.0, 1.0)
        b["wind"] += (b["wind_goal"] - b["wind"]) * min(1.0, dt * 3)
        ramp = 1 + 0.5 * b["t"] / BAL_DUR
        acc = (b["wind"] + BAL_UNSTABLE * b["p"]) * b["strength"] * ramp + b["hold"] * BAL_CONTROL
        b["v"] += acc * dt
        b["v"] *= max(0.0, 1 - BAL_DAMP * dt)
        b["p"] += b["v"] * dt
        if abs(b["p"]) >= 1.0:
            b["p"] = 1.0 if b["p"] > 0 else -1.0
            if b["shake"] <= 0 and abs(b["v"]) > 0.3:
                b["shake"] = 0.3
                b["popups"].append([BAL_CX + b["p"] * BAL_HALF * 0.8, 150, "BORDA!", RED, 0.8])
                play_sfx("bad")
            b["v"] = -b["v"] * 0.35
        if abs(b["p"]) <= b["zone"]:
            b["in_zone"] += dt
        b["walk"] += dt * (1 + abs(b["v"]) * 4)
        if b["t"] >= BAL_DUR:
            b["t"] = BAL_DUR
            b["phase"] = "finish"
            b["finish_t"] = 1.6
            b["popups"].append([BAL_CX, 130, "TEMPO!", GOLD, 1.4])
    elif ph == "finish":
        b["finish_t"] -= dt
        if b["finish_t"] <= 0:
            b["phase"] = "done"                                                      
            finish_balance()


def draw_balancer(surf, x, y, tilt, pose, t):
    """Personagem em pé na barra (pés em x, y), inclinado para o lado em que está caindo."""
    _bal_tmp.fill((0, 0, 0, 0))
    ok = draw_sprite(_bal_tmp, "runner_balance" if pose else "runner_idle", (170, 170), 150, t)
    if not ok:
        _proc_runner(_bal_tmp, 170, 170, "run", 0.0, False)
    rot = pygame.transform.rotate(_bal_tmp, tilt)
    surf.blit(rot, rot.get_rect(center=(int(x), int(y))))


