    for gx in range(beam[0] + 6, beam[0] + beam[2], 38):
        pygame.draw.line(ss, (78, 48, 26), (gx, by + 3), (gx + 14, by + 3), 1)
        pygame.draw.line(ss, (78, 48, 26), (gx + 8, by + 9), (gx + 24, by + 9), 1)
    zhalf = int(BAL_HALF * zone)
    pygame.draw.rect(ss, (76, 156, 84), (BAL_CX - zhalf, by, zhalf * 2, 14))
    pygame.draw.rect(ss, (150, 214, 130), (BAL_CX - zhalf, by, zhalf * 2, 3))
    pygame.draw.rect(ss, RED, (BAL_X0 - 24, by, 24, 14))
    pygame.draw.rect(ss, RED, (BAL_X1, by, 24, 14))
    pygame.draw.rect(ss, INK, beam, 3)
                
    x = BAL_CX + b["p"] * BAL_HALF
    tilt = -clamp(b["v"] * 16 + b["p"] * 10, -40, 40)
    pose = abs(b["v"]) > 0.55 or abs(b["p"]) > zone
    draw_balancer(ss, x, by, tilt, pose, b["walk"])
                      
    ss.blit(gauge_surface(zone), (BAL_GAUGE.x, BAL_GAUGE.y))
    pygame.draw.rect(ss, WHITE, BAL_GAUGE, 2)
    mx = BAL_CX + int(b["p"] * BAL_HALF)
    pygame.draw.line(ss, WHITE, (mx, BAL_GAUGE.y - 8), (mx, BAL_GAUGE.bottom + 8), 4)
    pygame.draw.polygon(ss, WHITE, [(mx - 9, BAL_GAUGE.y - 18), (mx + 9, BAL_GAUGE.y - 18), (mx, BAL_GAUGE.y - 3)])
                        
    draw_text("VENTO", 120, 34, 13, MUTED, align="left", bold=True)
    strength = abs(w)
    draw_arrow(ss, 230, 34, 9 + strength * 16, "RIGHT" if w >= 0 else "LEFT", mix(GREEN, RED, strength), WHITE)
           
