CER_REVEAL = 3.2
cer_t = 0.0
cer_revealed = False
confetti = []
CONFETTI_COLORS = [GOLD, PINK, CYAN, LIME, PURPLE, RED, WHITE]


def spawn_confetti(n, burst_mode=False):
    for _ in range(n):
        confetti.append([random.uniform(0, LW), random.uniform(-60, 120 if burst_mode else 0),
                         random.uniform(-70, 70), random.uniform(120, 340),
                         random.choice(CONFETTI_COLORS), random.randint(6, 12), random.randint(4, 8)])


def start_ceremony():
    global page, cer_t, cer_revealed
    cer_t = 0.0
    cer_revealed = False
    confetti.clear()
    page = "ceremony"


def ceremony_skip():
    global cer_t
    if cer_t < CER_REVEAL:
        cer_t = CER_REVEAL
    else:
        activate("final")


def update_ceremony(dt):
    global cer_t, cer_revealed
    cer_t += dt
    if cer_t >= CER_REVEAL and not cer_revealed:
        cer_revealed = True
        play_sfx("win")
        spawn_confetti(160, True)
    if cer_revealed and random.random() < 0.6:
        spawn_confetti(3)
    for c in confetti:
        c[0] += c[2] * dt
        c[1] += c[3] * dt
    confetti[:] = [c for c in confetti if c[1] < LH + 20]


def draw_oloko_win(x, y, size):
    draw_oloko(x, y, size, "win")


def draw_starburst(cx, cy, r_out, r_in, spikes, color, edge):
    pts = []
    for i in range(spikes * 2):
        ang = math.pi * i / spikes - math.pi / 2
        rr = r_out if i % 2 == 0 else r_in
        pts.append((cx + math.cos(ang) * rr, cy + math.sin(ang) * rr))
    pygame.draw.polygon(screen, color, pts)
    pygame.draw.polygon(screen, edge, pts, 3)


