def draw_logo(cx, top, max_w, max_h):
    sp = get_sprite("logo")
    if sp:
        img = sp["frames"][0]
        f = min(max_w / img.get_width(), max_h / img.get_height())
        size = (max(1, int(img.get_width() * f)), max(1, int(img.get_height() * f)))
        ck = ("logo", size)
        if ck not in _scaled_cache:
            _scaled_cache[ck] = pygame.transform.smoothscale(img, size)
        sc = _scaled_cache[ck]
                                        
        draw_glow(screen, cx, top + max_h // 2, 150, (255, 190, 110), 46)
        screen.blit(sc, sc.get_rect(midtop=(cx, top + (max_h - size[1]) // 2)))
        return
    key = ("logo_art", max_w, max_h)
    if key not in _scaled_cache:
        s = pygame.Surface((max_w, max_h), pygame.SRCALPHA)
        mx = max_w // 2
        draw_title("O  TORNEIO  DOS", mx, 38, 40, GOLD, spacing=5, surf=s)
        sy = 150
        draw_flourish(mx - 250, sy, 220, GOLD, s)
        draw_flourish(mx + 250, sy, 220, GOLD, s)
        draw_shield(s, mx, sy, 150, 168, WINE, GOLD)
        draw_title("12", mx, sy - 6, 104, GOLD, spacing=0, surf=s)
        draw_ribbon(s, mx, max_h - 22, 360, 30, WINE, "A TAÇA DAS CASAS", 15)
        _scaled_cache[key] = s
    screen.blit(_scaled_cache[key], (cx - max_w // 2, top))


