def screen_race():
    draw_background()
    header("PROVA 02 / REFLEXOS", "TRILHA DO CASTELO  •  SIGA OS SINAIS" if race_phase != "ready" else "LEIA O BRIEFING")
    if race_phase == "ready":
        screen_race_brief()
        return
    draw_race_scene()
    sx = sy = 0
    if shake_t > 0:
        amp = int(8 * shake_t / .35) + 1
        sx, sy = random.randint(-amp, amp), random.randint(-amp, amp)
    screen.set_clip(R(40, 100, SW, SH))
    screen.blit(scene_surf, (40 + sx, 100 + sy))
    screen.set_clip(None)
    scene_frame()
              
    up = race_commands[race_index + (1 if race_current else 0): race_index + (1 if race_current else 0) + 3]
    draw_text("PRÓXIMOS", 62, 124, 11, MUTED, align="left", bold=True)
    for i, d in enumerate(up):
        draw_arrow(screen, 76 + i * 36, 154, 11, d, dim(DIR_COLOR[d], .9))
                   
    if race_current and race_phase == "run":
        cp = R(440, 110, 400, 100)
        panel(cp, fill=PANEL, border=DIR_COLOR[race_current], shadow=False)
        draw_arrow(screen, cp.x + 54, cp.y + 46, 30, race_current, DIR_COLOR[race_current], WHITE)
        if race_ostate == "approach":
            draw_text(DIR_ACTION[race_current], cp.x + 110, cp.y + 30, 26, WHITE, align="left", bold=True)
            draw_text("contra " + DIR_OBS[race_current].lower(), cp.x + 110, cp.y + 58, 13,
                      DIR_COLOR[race_current], align="left", bold=True)
            frac = clamp(race_time_left / race_time_total, 0, 1)
            col = mix(RED, GREEN, frac) if frac < .5 else mix(GOLD, GREEN, (frac - .5) * 2)
            wood_bar(cp.x + 110, cp.y + 74, 270, 12, frac, col)
            draw_text(f"{race_time_left:.1f}s", cp.right - 14, cp.y + 30, 14, col, align="right", bold=True)
        else:
            draw_text("OK!", cp.x + 110, cp.y + 50, 34, GREEN, align="left", bold=True)
    if race_phase == "countdown":
        n = max(1, int(math.ceil(race_cd)))
        frac = race_cd - int(race_cd)
        draw_text(str(n), 640, 300, int(110 + 50 * (1 - frac)), WHITE, bold=True, glow=CYAN)
        draw_text("PREPARE-SE", 640, 390, 20, LIME, bold=True)
               
    draw_text(f"OBSTÁCULO {min(race_index + (1 if race_current else 0), RACE_TOTAL):02d}/{RACE_TOTAL}",
              640, 558, 12, GOLD, bold=True)
