def load_music_track(index, autoplay=True):
    global music_index, music_status, music_started, music_paused
    music_started = False
    if not PLAYLIST:
        music_status = "LISTA DE MÚSICAS VAZIA"
        return
    music_index = index % len(PLAYLIST)
    track = PLAYLIST[music_index]
    if not mixer_ready:
        music_status = "ÁUDIO INDISPONÍVEL NESTE DISPOSITIVO"
        return
    if not os.path.isfile(track["path"]):
        music_status = "ARQUIVO NÃO ENCONTRADO: COLOQUE A MÚSICA NA PASTA /music"
        return
    try:
        pygame.mixer.music.load(track["path"])
        pygame.mixer.music.set_volume(music_volume)
        if autoplay:
            pygame.mixer.music.play()
        music_started = bool(autoplay)
        music_paused = not autoplay
        music_status = "TOCANDO" if autoplay else "CARREGADA / PAUSADA"
    except pygame.error:
        music_status = "FORMATO DE ÁUDIO NÃO SUPORTADO"


