def go_back_from_music():
    global page
    page = music_return_page if music_return_page != "music" else "menu"


def activate(action):
    global page, nickname_error, difficulty, music_return_page, music_status, music_volume
    global ranking_difficulty, running, menu_index, nickname, music_started, music_paused
    if action == "quit":
        running = False
    elif action == "menu":
        page = "menu"
    elif action == "new":
        page = "houses"
    elif action == "music":
        music_return_page = page
        page = "music"
    elif action == "music_back":
        go_back_from_music()
    elif action.startswith("track:"):
        load_music_track(int(action.split(":", 1)[1]), autoplay=True)
    elif action == "music_toggle":
        if mixer_ready:
            try:
                if music_paused:
                    pygame.mixer.music.unpause()
                    music_paused = False
                    music_started = True
                    music_status = "TOCANDO"
                elif pygame.mixer.music.get_busy():
                    pygame.mixer.music.pause()
                    music_paused = True
                    music_status = "PAUSADA"
                else:
                    load_music_track(music_index, autoplay=True)
            except pygame.error:
                load_music_track(music_index, autoplay=True)
        else:
            music_status = "ÁUDIO INDISPONÍVEL NESTE DISPOSITIVO"
    elif action == "music_next":
        load_music_track(music_index + 1, autoplay=True)
    elif action == "music_prev":
        load_music_track(music_index - 1, autoplay=True)
    elif action == "volume_up":
        music_volume = min(1.0, music_volume + 0.1)
        if mixer_ready:
            pygame.mixer.music.set_volume(music_volume)
    elif action == "volume_down":
        music_volume = max(0.0, music_volume - 0.1)
        if mixer_ready:
            pygame.mixer.music.set_volume(music_volume)
    elif action == "houses":
        page = "houses"
    elif action.startswith("house:"):
        set_house(int(action.split(":", 1)[1]))
    elif action == "nickname":
        page = "nickname"
        nickname_error = ""
    elif action == "difficulty":
        nickname = nickname.strip()[:16]
        nickname_error = ""
        page = "difficulty"
    elif action == "skip_nickname":
        nickname = ""
        nickname_error = ""
        page = "difficulty"
    elif action.startswith("difficulty:"):
        difficulty = action.split(":", 1)[1]
        page = "controls"
    elif action == "controls_go":
        start_new_run()
    elif action == "quiz_next":
        quiz_next()
    elif action == "race_start":
        start_race()
    elif action == "race_go":
        if page == "race" and race_phase == "ready":
            race_begin()
    elif action.startswith("race_key:"):
        race_input(action.split(":", 1)[1])
    elif action == "ranking":
        ranking_difficulty = difficulty
        page = "ranking"
    elif action.startswith("rank:"):
        ranking_difficulty = action.split(":", 1)[1]
    elif action == "credits":
        page = "credits"
    elif action == "tournament":
        page = "tournament"
    elif action == "intro_next":
        intro_advance()
    elif action == "quiz_go":
        build_quiz_round()
        page = "quiz"
    elif action == "intro_balance":
        open_intro("equilibrio")
    elif action == "balance_go":
        start_balance()
    elif action == "result_next":
        activate(result_info["next"])
    elif action == "ceremony_go":
        start_ceremony()
    elif action == "ceremony_skip":
        ceremony_skip()
    elif action == "final":
        page = "final_result"
    elif action.startswith("answer:"):
        choose_answer(int(action.split(":", 1)[1]))


def click_at(pos):
    for rect, action in reversed(buttons):
        if rect.collidepoint(pos):
            if not action.startswith(("answer:", "race_key:")):
                play_sfx("click")
            activate(action)
            return


def add_nick_char(text):
    global nickname
    for ch in text or "":
        if ch.isprintable() and (ch.isalnum() or ch in " _-") and len(nickname) < 16:
            nickname += ch


def sync_text_input():
    """Abre o teclado do celular só na tela do apelido."""
    global text_input_on
    want = page == "nickname"
    if want != text_input_on:
        text_input_on = want
        try:
            (pygame.key.start_text_input if want else pygame.key.stop_text_input)()
        except Exception:
            pass


ACTIVE_PAGES = {"quiz", "race", "balance"}
esc_last = -9999
toast = {"text": "", "t": 0.0}


def show_toast(text, secs=1.6):
    toast["text"], toast["t"] = text, secs


def on_key(event):
    global page, menu_index, nickname, nickname_error, music_return_page, running, esc_last
    k = event.key
    if k == pygame.K_m and page != "nickname":
        if page == "music":
            go_back_from_music()
        else:
            music_return_page = page
            page = "music"
        return
    if k == pygame.K_ESCAPE:
        if page == "music":
            go_back_from_music()
        elif page in ACTIVE_PAGES and not (page == "race" and race_phase == "ready"):
            now = pygame.time.get_ticks()
            if now - esc_last < 1600:
                page = "menu"
            else:
                esc_last = now
                show_toast("APERTE ESC DE NOVO PARA ABANDONAR A PARTIDA")
        elif page != "menu":
            page = "menu"
        else:
            running = False
        return
    if page == "menu":
        if k == pygame.K_UP:
            menu_index = (menu_index - 1) % len(MENU_ITEMS)
        elif k == pygame.K_DOWN:
            menu_index = (menu_index + 1) % len(MENU_ITEMS)
        elif k in (pygame.K_RETURN, pygame.K_KP_ENTER, pygame.K_SPACE):
            activate(MENU_ITEMS[menu_index][1])
    elif page == "houses":
        if k in (pygame.K_RETURN, pygame.K_KP_ENTER):
            activate("nickname")
        elif k in KEY_DIR:
            step = {"LEFT": -1, "RIGHT": 1, "UP": -6, "DOWN": 6}[KEY_DIR[k]]
            n = len(HOUSES)
            for _ in range(n):                                            
                cand = SELECTED_HOUSE + step
                if cand < 0 or cand >= n:
                    cand = (SELECTED_HOUSE + (1 if step > 0 else -1)) % n if abs(step) == 1 else SELECTED_HOUSE
                if cand in UNLOCKED_HOUSES:
                    set_house(cand)
                    break
                step += 1 if step > 0 else -1
    elif page == "nickname":
        if k in (pygame.K_RETURN, pygame.K_KP_ENTER):
            nickname = nickname.strip()[:16]
            nickname_error = ""
            page = "difficulty"
        elif k == pygame.K_BACKSPACE:
            nickname = nickname[:-1]
        else:
            if not text_input_seen:
                add_nick_char(event.unicode)
    elif page == "difficulty":
        m = {pygame.K_1: 0, pygame.K_2: 1, pygame.K_3: 2}
        if k in m:
            activate("difficulty:" + DIFF_ORDER[m[k]])
    elif page == "controls":
        if k in (pygame.K_RETURN, pygame.K_KP_ENTER, pygame.K_SPACE):
            activate("controls_go")
    elif page == "quiz":
        m = {pygame.K_a: 0, pygame.K_b: 1, pygame.K_c: 2, pygame.K_d: 3,
             pygame.K_1: 0, pygame.K_2: 1, pygame.K_3: 2, pygame.K_4: 3}
        if quiz_answer is None and k in m:
            choose_answer(m[k])
        elif quiz_answer is not None and k in (pygame.K_RETURN, pygame.K_KP_ENTER, pygame.K_SPACE):
            quiz_next()
    elif page == "prova_result":
        if k in (pygame.K_RETURN, pygame.K_KP_ENTER, pygame.K_SPACE):
            activate(result_info["next"])
    elif page == "intro":
        if k in (pygame.K_RETURN, pygame.K_KP_ENTER, pygame.K_SPACE):
            intro_advance()
    elif page == "ceremony":
        if k in (pygame.K_RETURN, pygame.K_KP_ENTER, pygame.K_SPACE):
            ceremony_skip()
    elif page == "race":
        if race_phase == "ready" and k in (pygame.K_RETURN, pygame.K_KP_ENTER, pygame.K_SPACE):
            race_begin()
        elif k in KEY_DIR:
            race_input(KEY_DIR[k])


SCREENS = {"menu": screen_menu, "houses": screen_houses, "nickname": screen_nickname,
           "difficulty": screen_difficulty, "controls": screen_controls, "intro": screen_intro,
           "quiz": screen_quiz, "race": screen_race, "balance": screen_balance,
           "prova_result": screen_prova_result, "ceremony": screen_ceremony,
           "final_result": screen_final_result, "ranking": screen_ranking, "credits": screen_credits,
           "tournament": screen_tournament, "music": screen_music}


def run_frame(dt=None):
    global buttons, mouse_pos, running, menu_index, quiz_flash, text_input_seen, last_touch_ms, intro_t
    if dt is None:
        dt = min(clock.tick(60) / 1000.0, 0.05)
    buttons = []
    mouse_pos = to_logical(pygame.mouse.get_pos())
    if page == "race":
        update_race(dt)
    elif page == "balance":
        update_balance(dt)
    elif page == "ceremony":
        update_ceremony(dt)
    elif page == "intro":
        intro_t += dt
    quiz_flash = max(0.0, quiz_flash - dt)
                                                                   
    if mixer_ready and music_started and not music_paused:
        _music_poll[0] -= dt
        if _music_poll[0] <= 0:
            _music_poll[0] = 0.5
            if not pygame.mixer.music.get_busy():
                load_music_track(music_index + 1)
    sync_text_input()
    SCREENS[page]()
    if page != "music":
        draw_music_icon()
    if toast["t"] > 0:
        toast["t"] -= dt
        tr = R(340, 68, 600, 34)
        pygame.draw.rect(screen, (43, 26, 18), tr)
        pygame.draw.rect(screen, GOLD, tr, 2)
        draw_text(toast["text"], tr.centerx, tr.centery, 14, GOLD, bold=True)
    draw_frame_overlay()
    for event in pygame.event.get():
        if event.type == pygame.QUIT:
            running = False
        elif event.type == pygame.MOUSEMOTION and page == "menu":
            p = to_logical(event.pos)
            for i, r in enumerate(menu_rects):
                if r.collidepoint(p):
                    menu_index = i
        elif event.type == pygame.KEYDOWN:
            on_key(event)
        elif event.type == pygame.MOUSEBUTTONDOWN and event.button == 1:
                                                                                  
            if not getattr(event, "touch", False) and pygame.time.get_ticks() - last_touch_ms > 450:
                click_at(to_logical(event.pos))
        elif event.type == pygame.FINGERDOWN:
            last_touch_ms = pygame.time.get_ticks()
            ww, wh = pygame.display.get_surface().get_size()
            click_at(to_logical((event.x * ww, event.y * wh)))
        elif event.type == getattr(pygame, "TEXTINPUT", -1) and page == "nickname":
            text_input_seen = True
            add_nick_char(event.text)
    present()


                                                                                                                  
                                                                                                  
